INSERT INTO t_p78828167_tutor_platform_1.course_curricula (course_id,course_title,subject,grade_band,total_lessons,total_modules,estimated_hours,program_description,learning_outcomes,target_audience,prerequisites,methodology,final_project,certificate_available,generated_by,version,is_fallback,age_rating) VALUES (87,'Специалист по кибербезопасности с нуля: защита, пентест и SOC до трудоустройства','cybersec','adult',78,12,41,'Полноценный курс по кибербезопасности с нуля до уровня Junior с трудоустройством. Сети, Linux, криптография, веб-уязвимости OWASP, этичный пентест на легальных стендах, работа в SOC с SIEM, реагирование на инциденты, защита от социальной инженерии и облачная безопасность. 12 модулей, 78 уроков с практикой на стендах, разбором реальных инцидентов и чек-листами. Весь материал — про защиту и этичное тестирование с разрешения владельца.','["Понимаешь устройство сетей, Linux и криптографии как фундамент защиты","Находишь и закрываешь веб-уязвимости по методологии OWASP Top-10","Проводишь легальный пентест на стендах и оформляешь отчёт","Защищаешь сети и инфраструктуру: firewall, сегментация, VPN, IDS/IPS","Работаешь в SOC: SIEM, мониторинг, детектирование и реагирование на инциденты","Распознаёшь социальную инженерию и защищаешь людей и данные","Готов к трудоустройству джуниором: портфолио, резюме, сертификации"]'::jsonb,'Взрослые, кто хочет войти в одну из самых дефицитных и высокооплачиваемых ИТ-профессий — специалист по информационной безопасности. С нуля, опыт в ИТ не обязателен.','["специальных знаний не требуется","базовые навыки работы с компьютером","желание разбираться и практиковаться на стендах","английский на уровне чтения документации — плюс, но не обязателен"]'::jsonb,'От фундамента к практике: теория, разбор реальных атак и инцидентов, практика на легальных уязвимых стендах и в песочницах. Каждый модуль закрепляется заданием и чек-листом. Упор на защиту и этику: никаких противоправных инструкций, только легальное тестирование с согласия владельца.','Итоговый проект: провести аудит учебной системы, найти уязвимости и построить план защиты с отчётом.',true,'editorial_manual',1,false,'18+');
INSERT INTO t_p78828167_tutor_platform_1.course_curricula (course_id,course_title,subject,grade_band,total_lessons,total_modules,estimated_hours,program_description,learning_outcomes,target_audience,prerequisites,methodology,final_project,certificate_available,generated_by,version,is_fallback,age_rating) VALUES (88,'DevOps-инженер с нуля до Middle: Linux, Docker, Kubernetes, CI/CD и облако','devops','adult',80,12,42,'Практический курс на самую высокооплачиваемую ИТ-профессию: DevOps-инженер с нуля до уверенного Middle. Linux и Bash, Git, Docker и Kubernetes, CI/CD в GitLab и GitHub Actions, инфраструктура как код (Terraform, Ansible), мониторинг (Prometheus, Grafana, ELK), принципы SRE, облако и безопасность инфраструктуры. 12 модулей, 80 уроков с практикой на реальных проектах, разбором инцидентов и чек-листами.','["Уверенно работаешь в Linux и пишешь Bash-скрипты для автоматизации","Контейнеризуешь приложения в Docker и управляешь ими в Kubernetes","Строишь CI/CD пайплайны в GitLab CI и GitHub Actions с откатами","Разворачиваешь инфраструктуру кодом через Terraform и Ansible","Настраиваешь мониторинг и логирование (Prometheus, Grafana, ELK)","Применяешь принципы SRE: SLO, надёжность, реагирование на инциденты","Готов к трудоустройству Middle: портфолио с реальными пайплайнами и оффер"]'::jsonb,'Взрослые, кто хочет войти в самую высокооплачиваемую ИТ-профессию — DevOps-инженер (200 000–500 000 ₽). Подходит начинающим и разработчикам/админам, желающим перейти в DevOps.','["специальных знаний не требуется","базовые навыки работы с компьютером","готовность много практиковаться на реальных проектах","базовое понимание веб-разработки — плюс, но не обязательно"]'::jsonb,'Обучение через практику на реальных проектах: каждый инструмент осваивается руками — от контейнера до полного пайплайна и кластера. Теория даётся ровно для понимания, основной упор — на практические задания, сквозные проекты и разбор инцидентов. В финале — инфраструктура под ключ.','Итоговый проект: собрать инфраструктуру под ключ — приложение, CI/CD пайплайн, деплой в Kubernetes и мониторинг.',true,'editorial_manual',1,false,'18+');